<div class="page-heading admin-heading"><div><span class="eyebrow">Admission operations</span><h1>Applications</h1><p>Search, filter, assign and process every candidate record.</p></div><div class="heading-actions"><a class="button button-outline" href="<?= url('admin/applications/export') ?>">↓ Export CSV</a></div></div><div class="filter-tabs"><a class="<?= $status===''?'active':'' ?>" href="<?= url('admin/applications') ?>">All <b><?= array_sum(array_column($counts,'total')) ?></b></a><?php foreach($counts as $count):?><a class="<?= $status===$count['status']?'active':'' ?>" href="<?= url('admin/applications?status='.$count['status']) ?>"><?= e(ucwords(str_replace('_',' ',$count['status']))) ?> <b><?= e($count['total']) ?></b></a><?php endforeach?></div><section class="card application-table-card"><form class="table-filters" method="get" action="<?= url('admin/applications') ?>"><div class="search-field"><span>⌕</span><input name="q" value="<?= e($search) ?>" placeholder="Search name, application no., email or mobile"></div><select name="status"><option value="">All statuses</option><?php foreach(['draft','submitted','under_review','correction_required','selected','admitted','rejected'] as $option):?><option value="<?= $option ?>"<?= selected($status,$option) ?>><?= e(ucwords(str_replace('_',' ',$option))) ?></option><?php endforeach?></select><button class="button button-primary button-sm">Apply filters</button><?php if($status||$search):?><a href="<?= url('admin/applications') ?>">Clear</a><?php endif?></form><div class="table-wrap"><table class="application-table"><thead><tr><th><input type="checkbox" aria-label="Select all"></th><th>Applicant</th><th>Application no.</th><th>Contact</th><th>Submitted</th><th>Reviewer</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($applications as $application):?><tr><td><input type="checkbox" aria-label="Select <?= e($application['applicant_name']) ?>"></td><td><div class="person-cell"><span><?= e(strtoupper(substr($application['applicant_name'],0,1))) ?></span><div><b><?= e($application['applicant_name']) ?></b><small><?= e($application['cycle_name']) ?></small></div></div></td><td><b><?= e($application['application_number']?:'Draft') ?></b><small class="completion-small"><?= e($application['completion_percentage']) ?>% complete</small></td><td><?= e($application['email']) ?><small class="completion-small"><?= e($application['mobile']) ?></small></td><td><?= format_date($application['submitted_at']) ?></td><td><?= e($application['reviewer_name']?:'Unassigned') ?></td><td><span class="status-pill status-<?= e($application['status']) ?>"><?= e(ucwords(str_replace('_',' ',$application['status']))) ?></span></td><td><a class="row-action" href="<?= url('admin/applications/'.$application['id']) ?>">→</a></td></tr><?php endforeach?></tbody></table><?php if(!$applications):?><div class="empty-inline">No applications match the current filters.</div><?php endif?></div><div class="table-footer"><span>Showing <?= count($applications) ?> records</span><small>Release 1 is capped at 200 results per filtered view; use CSV export for the complete dataset.</small></div></section>
